import { createContext, ReactNode, useEffect, useState } from "react";
import { Expense } from "../types/types";
import { fetchBudget, updateBudget } from "../utils/budget-utils";

interface AppContextType {
  expenses: Expense[];
  setExpenses: React.Dispatch<React.SetStateAction<Expense[]>>;
  budget: number;
  setBudget: React.Dispatch<React.SetStateAction<number>>;
}


export const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [budget, setBudgetState] = useState<number>(0);

  // Load the budget from the backend when the context is first created
  useEffect(() => {
    const initializeBudget = async () => {
      try {
        const initialBudget = await fetchBudget();
        setBudgetState(initialBudget); // Set the initial budget from the backend
      } catch (error) {
        console.error("Failed to initialize budget:", error);
      }
    };

    initializeBudget();
  }, []);

  const setBudget = async (newBudget: number) => {
    try {
      const updatedBudget = await updateBudget(newBudget);
      setBudgetState(updatedBudget);
    } catch (error) {
      console.error("Failed to update budget:", error);
    }
  };
  
  return (
    <AppContext.Provider value={{ expenses, setExpenses, budget, setBudget }}>
      {children}
    </AppContext.Provider>
  );
};
